     SET template_pattern = $sx${BANKNAME}: Rs.{AMOUNT} {DEBITTYPE} from {ATMWITHDRAW} A/c XX{ACCOUNTLAST4} on {DATE}. Avl Bal:Rs.{BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"CUBBNK\", \"CUBSMS\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","AccountLast4":"accountLast4","CUB":"bankName","ATM":"atmWithdraw","withdrawn":"debitType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'f9e62b6c-69eb-5d38-883b-f191fa1aa867' AND template_pattern = $sx$CUB: Rs.{AMOUNT} withdrawn from ATM A/c XX{ACCOUNTLAST4} on {DATE}. Avl Bal:Rs.{BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME} Debit Card {ACCOUNTLAST4} used for Rs.{AMOUNT} at {MERCHANT} on {DATE}. Avl Bal Rs.{BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"BOBTXN\", \"BOBSMS\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","CardLast4":"accountLast4","BOB":"bankName"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fa2a66c3-a447-53ef-a6ba-d290108284d2' AND template_pattern = $sx$BOB Debit Card {ACCOUNTLAST4} used for Rs.{AMOUNT} at {MERCHANT} on {DATE}. Avl Bal Rs.{BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: INR {AMOUNT} {DEBITTYPE} from A/c XX{ACCOUNTLAST4} for POS txn at {MERCHANT} on {DATE}. Avl Bal:INR {BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"TMBBNK\", \"TMBSMS\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","AccountLast4":"accountLast4","TMB":"bankName","debited":"debitType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fa86f64f-b11b-5b2a-8a61-7b4c4064fa12' AND template_pattern = $sx$TMB: INR {AMOUNT} debited from A/c XX{ACCOUNTLAST4} for POS txn at {MERCHANT} on {DATE}. Avl Bal:INR {BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: Rs {AMOUNT} {DEBITTYPE} from A/c **{ACCOUNTLAST4} on {DATE} to {MERCHANT} via UPI. UPI Ref {REFERENCEID}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"BOISBN\", \"BOISMS\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","ReferenceId":"referenceId","AccountLast4":"accountLast4","BOI":"bankName","debited":"debitType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fb2372ca-bee2-5582-aef8-30d337e54c23' AND template_pattern = $sx$BOI: Rs {AMOUNT} debited from A/c **{ACCOUNTLAST4} on {DATE} to {MERCHANT} via UPI. UPI Ref {REFERENCEID}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: Rs.{AMOUNT} {DEBITTYPE} at {ATMWITHDRAW} from Ac XX{ACCOUNTLAST4} on {DATE}. Avl Bal Rs.{BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"KVBBNK\", \"KVBSMS\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","AccountLast4":"accountLast4","KVB":"bankName","ATM":"atmWithdraw","withdrawn":"debitType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fbeb3ee0-f602-5214-96bd-0e19beb4c469' AND template_pattern = $sx$KVB: Rs.{AMOUNT} withdrawn at ATM from Ac XX{ACCOUNTLAST4} on {DATE}. Avl Bal Rs.{BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: NEFT credit Rs.{AMOUNT} to A/c XX{ACCOUNTLAST4} from {MERCHANT} on {DATE}. Ref:{REFERENCEID}. Avl Bal:Rs.{BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"SIBSMS\", \"SIBBNK\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","ReferenceId":"referenceId","AccountLast4":"accountLast4","SIB":"bankName"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fde3ce43-c423-50b3-99f3-561c3a8e8961' AND template_pattern = $sx$SIB: NEFT credit Rs.{AMOUNT} to A/c XX{ACCOUNTLAST4} from {MERCHANT} on {DATE}. Ref:{REFERENCEID}. Avl Bal:Rs.{BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: Rs {AMOUNT} {CREDITTYPE} to A/c **{ACCOUNTLAST4} on {DATE} from {MERCHANT} via UPI. UPI Ref {REFERENCEID}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"DBSBNK\", \"DBSIND\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","ReferenceId":"referenceId","AccountLast4":"accountLast4","DBS Bank":"bankName","credited":"creditType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fe2f605f-d52d-5f56-9655-a74ea955b168' AND template_pattern = $sx$DBS Bank: Rs {AMOUNT} credited to A/c **{ACCOUNTLAST4} on {DATE} from {MERCHANT} via UPI. UPI Ref {REFERENCEID}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: INR {AMOUNT} {CREDITTYPE} to A/c XX{ACCOUNTLAST4} from {MERCHANT} via NEFT on {DATE}. Ref:{REFERENCEID}. Avl Bal:INR {BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"DCBBNK\", \"DCBSMS\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","ReferenceId":"referenceId","AccountLast4":"accountLast4","DCB Bank":"bankName","credited":"creditType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'febce3b6-63e0-5082-acdb-03c83ac5b2a4' AND template_pattern = $sx$DCB Bank: INR {AMOUNT} credited to A/c XX{ACCOUNTLAST4} from {MERCHANT} via NEFT on {DATE}. Ref:{REFERENCEID}. Avl Bal:INR {BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: EMI Rs.{AMOUNT} {DEBITTYPE} from Ac XX{ACCOUNTLAST4} on {DATE} towards {MERCHANT}. Avbl Bal:Rs.{BALANCE}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"PSBSMS\", \"PSBBNK\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","Balance":"balance","AccountLast4":"accountLast4","PSB":"bankName","debited":"debitType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'fee30c83-d0c9-5c24-87fc-084c7f6ceba8' AND template_pattern = $sx$PSB: EMI Rs.{AMOUNT} debited from Ac XX{ACCOUNTLAST4} on {DATE} towards {MERCHANT}. Avbl Bal:Rs.{BALANCE}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  UPDATE public.sms_template_rules
     SET template_pattern = $sx${BANKNAME}: Rs.{AMOUNT} {CREDITTYPE} to A/c **{ACCOUNTLAST4} via NEFT from {MERCHANT} on {DATE}. Ref {REFERENCEID}$sx$,
         extraction_map = $sx${"Date":"date","Payee":"merchant","Amount":"amount","__meta":"{\"smsKind\": \"payment\", \"category\": \"Shopping\", \"senderIds\": [\"KOTAKB\", \"KOTAKBN\"], \"dateFormat\": \"dd-MMM-yy\", \"titleOption\": \"merchant\"}","ReferenceId":"referenceId","AccountLast4":"accountLast4","Kotak Bank":"bankName","credited":"creditType"}$sx$::jsonb,
         updated_at = now()
   WHERE id = 'ff8c5fce-1c35-52c9-9dff-2889fe76b8ef' AND template_pattern = $sx$Kotak Bank: Rs.{AMOUNT} credited to A/c **{ACCOUNTLAST4} via NEFT from {MERCHANT} on {DATE}. Ref {REFERENCEID}$sx$;
  GET DIAGNOSTICS n = ROW_COUNT; total := total + n;
  IF total <> 268 THEN
    RAISE EXCEPTION 'Expected 268 updated rows, got % - rolled back (rows changed since script run?).', total;
  END IF;
END $upd$;
COMMIT;

-- ============ Section 4: verify ============
SELECT (SELECT count(*) FROM public.sms_template_rules) AS live_rows,
       (SELECT count(*) FROM public.sms_template_rules_backup_retag_20261029) AS backup_rows,
       (SELECT count(*) FROM public.sms_template_rules t JOIN public.sms_template_rules_backup_retag_20261029 b USING (id)
         WHERE t.template_pattern IS DISTINCT FROM b.template_pattern) AS rows_changed_expect_268;
SELECT (SELECT count(*) FROM public.sms_template_rules WHERE template_pattern LIKE '%{DEBITTYPE}%') AS debittype_now,
       (SELECT count(*) FROM public.sms_template_rules_backup_retag_20261029 WHERE template_pattern LIKE '%{DEBITTYPE}%') AS debittype_before,
       (SELECT count(*) FROM public.sms_template_rules WHERE template_pattern LIKE '%{CREDITTYPE}%') AS credittype_now,
       (SELECT count(*) FROM public.sms_template_rules_backup_retag_20261029 WHERE template_pattern LIKE '%{CREDITTYPE}%') AS credittype_before,
       (SELECT count(*) FROM public.sms_template_rules WHERE template_pattern LIKE '%{ATMWITHDRAW}%') AS atmwithdraw_now,
       (SELECT count(*) FROM public.sms_template_rules_backup_retag_20261029 WHERE template_pattern LIKE '%{ATMWITHDRAW}%') AS atmwithdraw_before,
       (SELECT count(*) FROM public.sms_template_rules WHERE template_pattern LIKE '%{ACCOUNTLAST4}%') AS accountlast4_now,
       (SELECT count(*) FROM public.sms_template_rules_backup_retag_20261029 WHERE template_pattern LIKE '%{ACCOUNTLAST4}%') AS accountlast4_before,
       (SELECT count(*) FROM public.sms_template_rules WHERE template_pattern LIKE '%{BANKNAME}%') AS bankname_now,
       (SELECT count(*) FROM public.sms_template_rules_backup_retag_20261029 WHERE template_pattern LIKE '%{BANKNAME}%') AS bankname_before;

